def minimum_swaps_to_order(N, M, initial_permutation, allowed_swaps):
    from collections import deque

    def serialize(perm):
        return ''.join(map(str, perm))

    def deserialize(s):
        return list(map(int, s))

    def generate_permutations(permutation, swaps):
        permutations = {serialize(permutation): []}
        queue = deque([serialize(permutation)])
        seen = {serialize(permutation)}

        while queue:
            current = queue.popleft()
            perm_list = deserialize(current)

            for a, b in swaps:
                new_perm = perm_list[:]
                new_perm[a-1], new_perm[b-1] = new_perm[b-1], new_perm[a-1]
                new_perm_serial = serialize(new_perm)

                if new_perm_serial not in seen:
                    seen.add(new_perm_serial)
                    permutations[current].append(new_perm_serial)
                    queue.append(new_perm_serial)

        return permutations

    def bfs(start, goal, neighbors):
        queue = deque([(start, 0)])
        visited = set([start])

        while queue:
            current, depth = queue.popleft()
            if current == goal:
                return depth

            for neighbor in neighbors.get(current, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, depth + 1))

        return float('inf')

    target = serialize(list(range(1, N + 1)))
    permutations = generate_permutations(initial_permutation, allowed_swaps)

    return bfs(serialize(initial_permutation), target, permutations)

