def minimum_swaps_to_sort(N, M, initial_permutation, allowed_swaps):
    from collections import deque

    def is_sorted(perm):
        return perm == list(range(1, N + 1))

    def apply_swap(perm, swap):
        a, b = swap
        perm[a - 1], perm[b - 1] = perm[b - 1], perm[a - 1]

    def bfs(initial_perm):
        queue = deque([(initial_perm, 0)])
        visited = set()
        visited.add(tuple(initial_perm))

        while queue:
            current_perm, swaps = queue.popleft()

            if is_sorted(current_perm):
                return swaps

            for swap in allowed_swaps:
                new_perm = current_perm[:]
                apply_swap(new_perm, swap)
                new_perm_tuple = tuple(new_perm)

                if new_perm_tuple not in visited:
                    visited.add(new_perm_tuple)
                    queue.append((new_perm, swaps + 1))

        return float('inf')

    return bfs(initial_permutation)


